{"cards": [{"node_code": "N_c5b7248c88da4a7f", "definition": "针对泥石流与沟谷灾害，研究灾害隐患点的排查、危险性评估、易发性区划及致灾因子识别的方法与技术。", "boundary": "本节点聚焦于灾害发生前的“识别”与“评估”阶段，旨在确定哪些沟谷或区域存在泥石流风险。涵盖基于地形地貌、地质条件、气象水文等因子的危险性评价模型，以及隐患点的筛选与分级。边界在于区分“识别评估”与“实时监测”，本节点侧重静态或准静态的风险空间分布与概率评估，而非灾害发生过程中的实时动态监测。", "includes": ["泥石流隐患点排查、危险性评价与易发性区划", "基于多源数据（遥感、GIS、气象）的致灾因子识别与分析", "沟谷灾害风险等级划分与空间分布规律研究"], "excludes": ["灾害发生过程中的实时动态监测与预警发布（归入监测预警）", "灾害发生后的工程治理与恢复重建（归入工程防治、恢复）"], "sibling_distinctions": [{"other_code": "N_ef2da19a01072fd0", "rule": "本节点侧重灾害发生前的静态风险识别与空间区划；兄弟节点侧重灾害发生过程中的实时动态监测与预警信号发布。"}, {"other_code": "N_cc18060cd5063194", "rule": "本节点侧重利用地质信息进行的宏观风险识别与评估；兄弟节点侧重具体的地质成因机制、物质组成及运动规律研究。"}], "cross_boundary_rule": "若研究重点为确定“哪里可能发生”及“风险多大”，归入本节点；若研究重点为“如何实时发现”及“何时发生”，归入监测预警节点。"}, {"node_code": "N_cc18060cd5063194", "definition": "研究泥石流与沟谷灾害的地质成因机制、物质来源、沟谷地貌特征及地质环境对灾害发育的控制作用。", "boundary": "本节点聚焦于灾害的“地质基础”与“成因机理”，深入分析物源区、水源区及流通区的地质条件。涵盖松散堆积物性质、沟谷形态、岩性结构、构造裂隙等对泥石流形成与运动的影响。边界在于区分“地质机理”与“工程应用”，本节点侧重自然地质过程的科学解释，而非具体的工程防治设计或监测技术。", "includes": ["泥石流物源、水源及沟道运动的地质成因与机理", "沟谷地貌、岩性、构造及松散堆积物对灾害的控制作用", "泥石流物质组成、运动参数及堆积特征的地质学研究"], "excludes": ["基于地质信息的宏观风险区划与隐患点排查（归入水灾害识别）", "具体的拦挡、排导等工程结构设计（归入工程防治）"], "sibling_distinctions": [{"other_code": "N_c5b7248c88da4a7f", "rule": "本节点侧重地质成因机制与物质运动规律的科学解释；兄弟节点侧重基于地质等因子的风险识别、评估与空间区划。"}, {"other_code": "N_15f8e92b67fcfea1", "rule": "本节点侧重灾害发生的自然地质背景与机理；兄弟节点侧重针对灾害的工程治理措施与技术。"}], "cross_boundary_rule": "若研究重点为“为什么发生”及“地质条件如何影响”，归入本节点；若研究重点为“哪里风险高”及“如何评估”，归入水灾害识别节点。"}, {"node_code": "N_ef2da19a01072fd0", "definition": "研究泥石流与沟谷灾害的实时监测技术、预警指标体系、预警模型及信息发布系统，旨在实现灾害的早期发现与及时预警。", "boundary": "本节点聚焦于灾害发生过程中的“动态监测”与“预警”环节。涵盖雨量、位移、流速等关键参数的实时监测手段，预警阈值确定、预警模型构建及预警信号发布流程。边界在于区分“监测预警”与“风险识别”，本节点侧重时间维度上的实时动态响应，而非空间维度上的静态风险区划。", "includes": ["泥石流沟谷的雨量、位移、流速等实时监测技术与设备", "预警指标体系、预警阈值确定及预警模型构建", "预警信息发布系统、应急响应联动及监测数据管理"], "excludes": ["灾害发生前的静态风险识别与易发性区划（归入水灾害识别）", "灾害发生后的工程治理与恢复重建（归入工程防治、恢复）"], "sibling_distinctions": [{"other_code": "N_c5b7248c88da4a7f", "rule": "本节点侧重灾害发生过程中的实时动态监测与预警；兄弟节点侧重灾害发生前的静态风险识别与空间区划。"}, {"other_code": "N_cc18060cd5063194", "rule": "本节点侧重基于实时数据的预警技术与系统；兄弟节点侧重地质成因机制与物质运动规律的基础研究。"}], "cross_boundary_rule": "若研究重点为“如何实时发现”及“何时预警”，归入本节点；若研究重点为“哪里风险高”及“如何评估”，归入水灾害识别节点。"}]}
